// Custom Cloudflare Worker entry: the OpenNext handler for every HTTP request, plus the daily
// cron that replaces the Azure Container Apps job. Cron Triggers call scheduled(), not a URL,
// so this calls the existing /api/cron/expiry-reminders route in-process with the same bearer
// secret it already checks -- the route's logic and auth are unchanged.

// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent until the first cf:build)
import { default as handler } from './.open-next/worker.js';

type Env = {
  CRON_SECRET: string;
  NEXT_PUBLIC_APP_URL?: string;
};

export default {
  fetch: handler.fetch,

  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const origin = env.NEXT_PUBLIC_APP_URL ?? 'https://prometheus.internal';
    const request = new Request(new URL('/api/cron/expiry-reminders', origin), {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (response: Response) => {
        if (!response.ok) {
          console.error(`expiry-reminders cron failed: ${response.status} ${await response.text()}`);
        }
      })
    );
  },
} satisfies ExportedHandler<Env>;
